actions.script:
try {
    if (effectiveFrom) effectiveFrom = java.sql.Date.valueOf(java.time.LocalDate.parse(effectiveFrom.toString()))
    if (effectiveThru) effectiveThru = java.sql.Date.valueOf(java.time.LocalDate.parse(effectiveThru.toString()))
} catch (Exception ignored) { ec.message.addError('Enter valid dates in YYYY-MM-DD format.'); }

def _org = ec.user.isInGroup('ADMIN') ? null : (ec.service.sync().name('zenith.tax.TaxAccessServices.get#AuthorizedActiveOrganization').call().activeOrgId ?: '_NA_')
def q = ec.entity.find("zenith.erp.tax.TaxExemption"); if (_org) q.condition("organizationPartyId", _org)
def rows = q.orderBy("-exemptionId").list()
def df = new java.text.SimpleDateFormat("yyyy-MM-dd")
def esc = { v -> def s = (v == null) ? '' : v.toString(); if (v instanceof CharSequence && s ==~ /(?s)^[=+@\-\t\r].*/) s = "'" + s; (s.contains(',') || s.contains('"') || s.contains("\n")) ? ('"' + s.replace('"','""') + '"') : s }
def sb = new StringBuilder("ID,Product,Party,Type,Authority,Rule No,From,To,Status\n")
rows.each { sb.append([esc(it.exemptionId), esc(it.productId), esc(it.partyId), esc(it.exemptionTypeEnumId), esc(it.taxAuthorityId), esc(it.exemptionNumber), esc(it.effectiveFrom != null ? df.format(it.effectiveFrom) : ''), esc(it.effectiveThru != null ? df.format(it.effectiveThru) : ''), esc(it.isActive == 'Y' ? 'Active' : 'Inactive')].join(',')).append("\n") }
ec.web.sendTextResponse(sb.toString(), "text/csv", "TaxExemptions.csv")

// Option lists for the New Tax Exemption modal (also reused to label the table)
def _uri = (ec.web?.request?.requestURI ?: ''); def _zi = _uri.indexOf('/zenith/'); appBase = _zi > 0 ? _uri.substring(0, _zi) : ''
def _o = ec.service.sync().name('zenith.tax.TaxAccessServices.get#AuthorizedActiveOrganization').call().activeOrgId ?: '_NA_'
def _pf = ec.entity.find("mantle.party.PartyDetail"); if (_o) _pf.condition("ownerPartyId", _o)
parties = _pf.orderBy("organizationName,lastName,firstName").limit(1000).list().collect { p -> def nm = p.organizationName ?: ((((p.firstName ?: '') + ' ' + (p.lastName ?: '')).trim()) ?: p.partyId); [id: p.partyId, label: nm] }
def _prf = ec.entity.find("mantle.product.Product"); if (_o) _prf.condition("ownerPartyId", _o)
products = _prf.orderBy("pseudoId").limit(1000).list().collect { pr -> [id: pr.productId, label: ((pr.pseudoId ?: '') + ' - ' + (pr.productName ?: ''))] }
taxAuthorities = ec.entity.find("zenith.erp.tax.TaxAuthority").condition("isActive", "Y").orderBy("description").list().collect { a -> [id: a.taxAuthorityId, label: a.description ?: a.taxAuthorityId] }
exemptionTypes = ec.entity.find("moqui.basic.Enumeration").condition("enumTypeId", "TaxExemptionType").orderBy("sequenceNum").list().collect { e -> [id: e.enumId, label: e.description ?: e.enumId] }

// id → label maps for the table
def partyMap = [:]; parties.each { partyMap[it.id] = it.label }
def productMap = [:]; products.each { productMap[it.id] = it.label }
def authMap = [:]; taxAuthorities.each { authMap[it.id] = it.label }
def typeMap = [:]; exemptionTypes.each { typeMap[it.id] = it.label }

def rcTypes = ['TexReverseCharge'] as Set
def noGstTypes = ['TexFull','TexZeroRated','TexExport','TexSez'] as Set
def _pal = ['#F97316','#2563EB','#10B981','#7C3AED','#DC2626','#0EA5E9','#D97706']
def _init = { nm -> if (!nm) return '?'; def ps = nm.trim().split('\\s+'); def a = (ps[0] ? ps[0][0] : ''); def b = ((ps.size()>1 && ps[-1]) ? ps[-1][0] : ''); return (a + b).toUpperCase() }
def sdfP = new java.text.SimpleDateFormat("dd MMM yyyy")

exRows = (taxExemptions ?: []).collect { ex ->
    def prodLabel = productMap[ex.productId]
    if (!prodLabel && ex.productId) { try { def pr = ec.entity.find("mantle.product.Product").condition("productId", ex.productId).selectField("pseudoId").selectField("productName").one(); if (pr) prodLabel = ((pr.pseudoId ?: '') + ' - ' + (pr.productName ?: '')).trim() } catch (Exception e) {} }
    if (!prodLabel) prodLabel = ex.productId
    def ptyName = partyMap[ex.partyId]
    if (!ptyName && ex.partyId) { try { def pt = ec.entity.find("mantle.party.PartyDetail").condition("partyId", ex.partyId).one(); if (pt) ptyName = (pt.organizationName ?: (((pt.firstName ?: '') + ' ' + (pt.lastName ?: '')).trim())) } catch (Exception e) {} }
    if (!ptyName) ptyName = ex.partyId
    def ptyRole = 'Customer'
    try { def roles = ec.entity.find("mantle.party.PartyRole").condition("partyId", ex.partyId).selectField("roleTypeId").list()*.roleTypeId
        if (roles.contains('Vendor') || roles.contains('Supplier')) ptyRole = 'Vendor' } catch (Exception e) {}
    def tcat = rcTypes.contains(ex.exemptionTypeEnumId) ? 'rc' : (noGstTypes.contains(ex.exemptionTypeEnumId) ? 'nogst' : 'other')
    def typeLabel = (tcat == 'rc') ? 'Reverse Charge' : (typeMap[ex.exemptionTypeEnumId] ?: 'Exemption')
    def typeDesc = (tcat == 'rc') ? 'Buyer pays the GST instead of seller' : ((tcat == 'nogst') ? 'No GST charged for selected items/parties' : 'Special provision / government order')
    def h = Math.abs(((ptyName ?: '') as String).hashCode())
    [ id: ex.exemptionId, prod: prodLabel,
      pty: ptyName, ptyRole: ptyRole, initials: _init(ptyName), avColor: _pal[h % _pal.size()],
      tcat: tcat, typeLabel: typeLabel, typeDesc: typeDesc,
      auth: (authMap[ex.taxAuthorityId] ?: (ex.taxAuthorityId ?: '—')),
      ruleNo: (ex.exemptionNumber ?: '—'),
      fromStr: (ex.effectiveFrom ? sdfP.format(ex.effectiveFrom) : '—'),
      toStr: (ex.effectiveThru ? sdfP.format(ex.effectiveThru) : '—'),
      active: (ex.isActive == 'Y'),
      since: (ex.effectiveFrom ? sdfP.format(ex.effectiveFrom) : '—') ]
}
exCount = exRows.size()

def actives = (taxExemptions ?: []).findAll { it.isActive == 'Y' }
statTotal = actives.size()
statNoGst = actives.findAll { noGstTypes.contains(it.exemptionTypeEnumId) }.size()
statRc = actives.findAll { rcTypes.contains(it.exemptionTypeEnumId) }.size()
def _now = ec.user.nowTimestamp; def _30 = new java.sql.Timestamp(_now.getTime() + 30L*24*3600*1000)
statExpiry = actives.findAll { it.effectiveThru != null && !it.effectiveThru.before(_now) && it.effectiveThru.before(_30) }.size()
